import{_ as i,l,o as e,c as s,v as r,p as n,x as t,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"分层与端到端","description":"","frontmatter":{"title":"分层与端到端","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/layering-e2e.md","filePath":"cs/layering-e2e.md","lastUpdated":1789023840000}'),h={name:"cs/layering-e2e.md"};function E(B,a,A,_,m,f){const o=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="分层与端到端" tabindex="-1">分层与端到端 <a class="header-anchor" href="#分层与端到端" aria-label="Permalink to &quot;分层与端到端&quot;">​</a></h1><div class="epigraph"><p>功能只应放在端系统能完成且正确的那一层；下层的「几乎正确」不能代替端到端的检查。</p><footer>—— 据 Saltzer, Reed and Clark, End-to-End Arguments in System Design, ACM TOCS 1984 整理</footer></div><p><a href="/cs/virtio">上一课</a>把客机 I/O 收到半虚拟化队列；操作系统课到此结束。<a href="/cs/io-dma">I/O 与 DMA</a>已经能把设备字节搬进一台机器的内存。两台机器之间还没有共享的名字：对方的缓冲不是我的物理帧，总线事务过不了机箱。缺口是<strong>互连</strong>：先约定分层，再用端到端论证约束「可靠性该放哪」。本课不把 MAC 地址写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若把文件语义（完整字节流、进程描述符）直接铺到电线上，每种应用都要重做调制。若只在链路上做完美可靠，文件传输仍要在两端核对：链路重传挡不住中间节点内存出错。Saltzer 等的论证：文件传送的正确性只能在两端用校验与重试保证；链路层的努力是性能优化，不是正确性替代。缺口是这句分工，加上分层：相邻层通过接口服务，对等层通过协议。</p><p>套接字需要<a href="/cs/process-image">进程</a>与<a href="/cs/file-bytestream">文件</a>，但本课还没有端口；只承认「主机」将出现。</p><p><span class="marginnote">端到端不是「不要下层校验」。下层校验降低端到端重传频率。论证反对的是：把端到端才能做对的功能只放在下层并声称已经够了。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>教学用五层直觉：应用、传输、网络、链路、物理。IP 把异构链路连成互联网（Cerf 与 Kahn 的分组互连）；传输把进程接上；链路把相邻跳接上。本课不把 OSI 七层当必须背诵的真理，只要求：每层有 PDU 与对等协议，上层 PDU 是下层的载荷。</p>',9)),(e(),n(c,null,{default:t(()=>[p(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20APP%5B%22%E5%BA%94%E7%94%A8%22%5D%20--%3E%20TR%5B%22%E4%BC%A0%E8%BE%93%3A%20%E8%BF%9B%E7%A8%8B%E5%88%B0%E8%BF%9B%E7%A8%8B%22%5D%0A%20%20TR%20--%3E%20NET%5B%22%E7%BD%91%E7%BB%9C%3A%20%E4%B8%BB%E6%9C%BA%E5%88%B0%E4%B8%BB%E6%9C%BA%22%5D%0A%20%20NET%20--%3E%20LINK%5B%22%E9%93%BE%E8%B7%AF%3A%20%E4%B8%80%E8%B7%B3%22%5D%0A%20%20LINK%20--%3E%20PHY%5B%22%E7%89%A9%E7%90%86%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>分层让 DMA 进来的字节被解释成帧、包、段，而不是「又一份磁盘块」。端到端论证解释后课 TCP 校验与应用层校验为何同时存在：磁盘与路由器内存都不在文件两端的信任域里。VFS 的 <code>read</code> 在一台机器上结束；跨机器必须把「流」做成协议，而不是共享 inode。</p><p>本课之后，第一跳如何给帧加上可转发的链路地址，下一课 MAC。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入跨层优化的全部例外（有意识地打破分层），不把电信信令网当互联网主干。也不把端到端与「网络中立」政策混成一课。加密与认证的端到端是更后的 TLS 入口，这里只借 Saltzer 的文件传输例子。</p><p>把加密只放在链路层，换一条跳就明文：这也是端到端要把机密性放到真正两端的理由，后课 TLS 入口会收回。</p><p>后课默认：功能按层放；正确性在真正的两端收口。相邻机器上的一跳需要帧与硬件地址，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DMA 只解决单机搬字节；跨机要协议分层。</li><li>端到端：下层优化性能，两端保证正确。</li><li>一跳的帧与 MAC 是下一课。</li><li>出处：Saltzer, Reed and Clark, <em>ACM TOCS</em> 1984；Cerf and Kahn, 1974；Kurose and Ross。</li></ul>',9))])}const C=i(h,[["render",E]]);export{T as __pageData,C as default};
